import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadRussoOne = makeLoadFont('RussoOne');
const loadRajdhani = makeLoadFont('Rajdhani');

// Load premium fonts at module level
const { fontFamily: russoFont } = loadRussoOne();
const { fontFamily: rajdhaniFont } = loadRajdhani();

// Responsive Grid component matching the original HUD/sports grid
